def main() -> int:
    args = parser().parse_args()
    if args.command == "doctor":
        report = doctor_report()
        report["runtime"] = deployment_plan()
        emit(report)
        return 0 if report["status"] == "ready" else 3
    if args.command == "init":
        emit(initialize(args.repo.resolve(), args.out.resolve(), args.format, args.scope_path, args.entry, args.expand_depth, args.expand_direction, args.include, args.init_git, args.initial_commit_message, args.git_author_name, args.git_author_email, args.csharp_solution, args.csharp_project, args.allow_dotnet_restore, args.page_config.resolve() if args.page_config else None))
    elif args.command == "run":
        emit(run_fast(repo=args.repo.resolve() if args.repo else None, output=args.out.resolve(), format_name=args.format, resume=args.resume, scope_paths=args.scope_path, entries=args.entry, expand_depth=args.expand_depth, expand_direction=args.expand_direction, includes=args.include, init_git=args.init_git, initial_commit_message=args.initial_commit_message, git_author_name=args.git_author_name, git_author_email=args.git_author_email, csharp_solution=args.csharp_solution, csharp_project=args.csharp_project, allow_dotnet_restore=args.allow_dotnet_restore, page_config_path=args.page_config.resolve() if args.page_config else None))
    elif args.command == "build-chunk":
        emit(build_chunk(args.out.resolve(), args.chunk, args.stage))
    elif args.command == "review-chunk":
        emit(review_chunk(args.out.resolve(), args.chunk, args.review.resolve()))
    elif args.command == "review-pack":
        emit(review_pack(args.out.resolve(), args.pack, args.review.resolve()))
    elif args.command == "audit":
        result = audit_global(args.out.resolve()) if args.global_audit else audit_chunk(args.out.resolve(), args.chunk)
        emit(result)
        return 0 if result.get("status") == "passed" else 5
    elif args.command == "merge":
        emit(merge(args.out.resolve()))
    elif args.command == "finalize":
        emit(finalize(args.out.resolve()))
    elif args.command == "status":
        emit(status(args.out.resolve()))
    elif args.command == "migrate":
        if args.migration_command == "start":
            result = migrate_output(args.from_out, args.repo, args.out, args.format)
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        if args.migration_command == "status":
            result = migration_status(args.out)
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        result = audit_migration(args.out, require_complete_reviews=not args.allow_pending_reviews)
        emit(result)
        return 0 if result.get("status") == "passed" else 4 if result.get("status") == "pending-agent-review" else 5
    elif args.command == "context":
        emit(build_context(args.out.resolve(), args.module, args.entry))
    elif args.command == "query":
        emit(query_graph(args.out.resolve(), args.question, args.budget, args.dfs))
    elif args.command == "retrieve":
        output = args.out.resolve()
        if (output / "machine/knowledge.sqlite").is_file():
            emit(retrieve_machine(output, args.question, args.budget, args.max_pages, args.profile))
        else:
            emit(retrieve(output, args.question, args.budget, args.max_pages))
    elif args.command == "reindex":
        output = args.out.resolve()
        emit({"status": "passed", "machine": build_machine_knowledge(output), "compatibility": build_agent_index(output)})
    elif args.command == "coverage":
        emit(machine_coverage(args.out.resolve()))
    elif args.command == "entity":
        emit(entity_lookup(args.out.resolve(), args.selector))
    elif args.command == "neighbors":
        emit(neighbor_lookup(args.out.resolve(), args.selector, args.depth, args.relation, args.limit))
    elif args.command == "source":
        emit(source_lookup(args.out.resolve(), args.selector, args.context_lines))
    elif args.command == "changes":
        emit(change_documents(args.out.resolve(), args.kind, args.limit))
    elif args.command == "path":
        emit(shortest_path(args.out.resolve(), args.source, args.target))
    elif args.command == "explain":
        emit(explain_node(args.out.resolve(), args.selector))
    elif args.command == "record":
        emit(
            record_note(
                args.out.resolve(),
                args.kind,
                args.title,
                args.body.resolve(),
                args.link,
                (args.from_query or args.from_pack).resolve() if (args.from_query or args.from_pack) else None,
                args.append,
            )
        )
    elif args.command == "workspace":
        if args.workspace_command == "sync":
            output = args.out.resolve()
            workspace = sync_workspace(output, args.repo.resolve())
            emit({**workspace, "machine": sync_workspace_changes(output)})
        elif args.workspace_command == "status":
            emit(workspace_status(args.out.resolve()))
        elif args.workspace_command == "session-start":
            emit(start_session(args.out.resolve(), args.repo.resolve(), args.question, args.budget, args.profile))
        elif args.workspace_command == "session-finish":
            emit(finish_session(args.out.resolve(), args.repo.resolve(), args.session, args.summary.resolve(), args.title))
        else:
            emit(sessions_status(args.out.resolve()))
    elif args.command == "automation":
        if args.automation_command == "register":
            emit(
                register_project(
                    args.repo,
                    args.out,
                    args.registry,
                    args.harness or None,
                    max_field_chars=args.max_field_chars,
                    custom_redactions=args.redact,
                    workspace_roots=args.workspace_root,
                )
            )
        elif args.automation_command == "unregister":
            emit(unregister_project(args.repo, args.registry))
        elif args.automation_command == "registry":
            emit(registry_status(args.registry))
        elif args.automation_command == "activate":
            emit(activate_skill_session(args.harness, args.session_id, args.cwd, args.registry, args.source))
        elif args.automation_command in {"ingest", "hook"}:
            try:
                raw_text = args.event.read_text(encoding="utf-8-sig") if args.event else sys.stdin.read()
                raw = json.loads(raw_text)
                result = ingest_event(args.harness, raw, args.registry)
                emit(result["hook_output"] if args.automation_command == "hook" else result)
            except Exception as exc:
                if args.automation_command != "hook":
                    raise
                print(f"CKB_AUTOMATION_HOOK_ERROR={type(exc).__name__}: {exc}", file=sys.stderr)
                emit({})
        elif args.automation_command == "drain":
            emit(drain_automation(args.out, args.limit))
        elif args.automation_command == "retry":
            emit(retry_failed_automation(args.out, args.limit))
        elif args.automation_command == "status":
            emit(automation_status(args.out))
        elif args.automation_command == "pending":
            emit(pending_automation_reviews(args.out, args.all))
        elif args.automation_command == "review":
            emit(review_automation(args.out, args.review))
        elif args.automation_command == "review-template":
            emit(write_automation_review_template(args.out, args.review_id, args.write))
        else:
            emit(render_integration(args.harness, args.destination, args.python, args.ckb, args.registry, force=args.force))
    elif args.command == "relink":
        emit(relink_sources(args.out.resolve(), args.repo_root.resolve(), args.editor, args.source_view, args.custom_template))
    elif args.command == "showcase":
        emit(package_showcase(args.dist.resolve(), args.sample))
    elif args.command == "page-config":
        if args.write:
            emit(write_page_config(args.write, DEFAULT_PAGE_CONFIG, overwrite=args.force))
        else:
            config, source = load_page_config(args.validate)
            emit({"schema_version": config["schema_version"], "status": "passed", "source": source, "sha256": page_config_sha256(config), "normalized": config})
    elif args.command == "runtime":
        if args.runtime_command == "plan":
            emit(deployment_plan())
        elif args.runtime_command == "deploy":
            emit(deploy_runtime(args.accept))
        elif args.runtime_command == "remove":
            emit(remove_runtime(args.lock_id))
    return 0

"""Harness-neutral conversation and modification automation for CKB.

Every host adapter emits a small JSON event.  This module owns the durable
contract: explicit project registration, deterministic normalization and
redaction, write-ahead spooling, idempotent SQLite ingestion, turn/session
aggregation, and Agent-reviewed promotion into the human knowledge layer.
"""

from __future__ import annotations

from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import re
import sqlite3
import time
from typing import Any, Iterator
import uuid

from .common import CkbError, json_load, json_write, run, safe_title, stable_id, utc_now


AUTOMATION_SCHEMA_VERSION = 3
AUTOMATION_DATABASE = "machine/automation.sqlite"
REQUIRED_SKILL = "code-knowledge-builder"
SUPPORTED_HARNESSES = {
    "codex",
    "claude",
    "opencode",
    "opencode-v2",
    "dsh",
    "gemini",
    "copilot",
    "cursor",
    "generic",
}
CANONICAL_EVENTS = {
    "skill.applied",
    "session.start",
    "turn.prompt",
    "turn.assistant",
    "tool.result",
    "file.changed",
    "turn.stop",
    "compact.before",
    "compact.after",
    "session.end",
}
_SKILL_PROMPT = re.compile(r"(?<![A-Za-z0-9_-])(?:\$\s*|/)code-knowledge-builder(?![A-Za-z0-9_-])", re.IGNORECASE)
_SKILL_METADATA_KEYS = {
    "active_skill",
    "active_skills",
    "applied_skill",
    "applied_skills",
    "command_name",
    "commandname",
    "skill",
    "skill_name",
    "skillname",
    "skills",
}
_SESSION_ENVIRONMENT = {
    "codex": ("CODEX_SESSION_ID", "CODEX_THREAD_ID"),
    "claude": ("CLAUDE_SESSION_ID",),
    "opencode": ("OPENCODE_SESSION_ID",),
    "opencode-v2": ("OPENCODE_SESSION_ID",),
    "dsh": ("DSH_SESSION_ID",),
    "gemini": ("GEMINI_SESSION_ID",),
    "copilot": ("COPILOT_SESSION_ID",),
    "cursor": ("CURSOR_SESSION_ID",),
    "generic": ("CKB_SESSION_ID",),
}
_IGNORED_CHANGE_PARTS = {
    ".git",
    ".cache",
    ".mypy_cache",
    ".pytest_cache",
    ".ruff_cache",
    ".venv",
    "__pycache__",
    "bin",
    "node_modules",
    "obj",
    "venv",
}
_IGNORED_CHANGE_SUFFIXES = {".pyc", ".pyo"}
_CHANGE_HEADINGS = ("修改内容", "修改原因", "验证结果")
_SENSITIVE_KEY = re.compile(
    r"(?:api[_-]?key|access[_-]?token|refresh[_-]?token|authorization|password|passwd|secret|cookie|private[_-]?key)",
    re.IGNORECASE,
)
_DEFAULT_STRING_REDACTIONS: tuple[tuple[str, re.Pattern[str]], ...] = (
    (
        "authorization",
        re.compile(r"(?i)\b(?:authorization\s*:\s*)?(?:bearer|basic)\s+[A-Za-z0-9._~+/=-]{8,}"),
    ),
    (
        "credential-assignment",
        re.compile(
            r"(?i)\b(api[_-]?key|token|access[_-]?token|refresh[_-]?token|password|passwd|secret)\b"
            r"(\s*[:=]\s*)([^\s,;\]\}\)\"']{4,}|\"[^\"]{4,}\"|'[^']{4,}')"
        ),
    ),
    (
        "private-key",
        re.compile(r"-----BEGIN [^-\r\n]*PRIVATE KEY-----[\s\S]*?-----END [^-\r\n]*PRIVATE KEY-----"),
    ),
)
_PATH_KEYS = {
    "file_path",
    "filepath",
    "path",
    "output_path",
    "outputpath",
    "output_paths",
    "outputpaths",
    "changed_path",
    "changed_paths",
}
_PATCH_PATH = re.compile(r"^\*\*\*\s+(?:Add|Update|Delete)\s+File:\s*(.+?)\s*$", re.MULTILINE)


def default_registry_path() -> Path:
    configured = os.environ.get("CKB_AUTOMATION_REGISTRY")
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "automation-registry.json"


def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    value = os.path.normcase(os.path.normpath(value))
    return value.replace("\\", "/").rstrip("/")


def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")


def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"schema_version": AUTOMATION_SCHEMA_VERSION, "projects": []}
    value = json_load(path)
    if value.get("schema_version") in {1, 2} and isinstance(value.get("projects"), list):
        # Earlier registries matched either the repository only or repository
        # plus workspace roots.  Read both through the current hard activation
        # contract; the next registry write upgrades the document atomically.
        value = {
            **value,
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "projects": [
                {
                    **item,
                    "workspace_roots": list(item.get("workspace_roots") or []),
                    "required_skill": REQUIRED_SKILL,
                    "require_skill_activation": True,
                }
                for item in value["projects"]
            ],
        }
    if value.get("schema_version") != AUTOMATION_SCHEMA_VERSION or not isinstance(value.get("projects"), list):
        raise CkbError(f"unsupported automation registry: {path}")
    for item in value["projects"]:
        item.setdefault("workspace_roots", [])
        item["required_skill"] = REQUIRED_SKILL
        item["require_skill_activation"] = True
    return value


def register_project(
    repo: Path,
    output: Path,
    registry_path: Path | None = None,
    harnesses: list[str] | None = None,
    *,
    max_field_chars: int = 12_000,
    custom_redactions: list[str] | None = None,
    workspace_roots: list[Path] | None = None,
) -> dict[str, Any]:
    repo = repo.resolve()
    output = output.resolve()
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    if not repo.is_dir():
        raise CkbError(f"automation repository does not exist: {repo}")
    if not (output / "state.json").is_file():
        raise CkbError(f"automation requires a CKB output with state.json: {output}")
    selected = sorted(set(harnesses or SUPPORTED_HARNESSES))
    unsupported = sorted(set(selected) - SUPPORTED_HARNESSES)
    if unsupported:
        raise CkbError(f"unsupported automation harnesses: {unsupported}")
    if max_field_chars < 256 or max_field_chars > 1_000_000:
        raise CkbError("automation max-field-chars must be between 256 and 1000000")
    patterns = list(custom_redactions or [])
    for pattern in patterns:
        try:
            re.compile(pattern)
        except re.error as exc:
            raise CkbError(f"invalid custom redaction regex: {pattern}: {exc}") from exc
    value = _read_registry(registry)
    key = _path_key(repo)
    resolved_workspaces = sorted(
        {str(Path(item).expanduser().resolve()) for item in (workspace_roots or [])},
        key=_path_key,
    )
    for root in resolved_workspaces:
        if not Path(root).is_dir():
            raise CkbError(f"automation workspace root does not exist: {root}")
        if not (_is_within(repo, root) or _is_within(root, repo)):
            raise CkbError(f"automation workspace root must contain the repository or be inside it: {root}")
    for item in value["projects"]:
        if _path_key(item.get("repo_root", "")) == key:
            continue
        overlap = sorted(set(map(_path_key, item.get("workspace_roots", []))) & set(map(_path_key, resolved_workspaces)))
        if overlap:
            raise CkbError(
                "automation workspace root is already assigned to another repository: "
                f"{overlap}; use a narrower workspace root"
            )
    projects = [item for item in value["projects"] if _path_key(item.get("repo_root", "")) != key]
    entry = {
        "registration_id": stable_id("reg", key),
        "enabled": True,
        "repo_root": str(repo),
        "knowledge_output": str(output),
        "workspace_roots": resolved_workspaces,
        "harnesses": selected,
        "max_field_chars": max_field_chars,
        "custom_redactions": patterns,
        "required_skill": REQUIRED_SKILL,
        "require_skill_activation": True,
        "registered_at_utc": utc_now(),
    }
    projects.append(entry)
    value["projects"] = sorted(projects, key=lambda item: _path_key(item["repo_root"]))
    json_write(registry, value)
    initialize_automation_database(output)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "registered",
        "registry": str(registry),
        "project": entry,
    }


def unregister_project(repo: Path, registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    key = _path_key(repo.resolve())
    before = len(value["projects"])
    value["projects"] = [item for item in value["projects"] if _path_key(item.get("repo_root", "")) != key]
    json_write(registry, value)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "unregistered" if len(value["projects"]) != before else "not-registered",
        "registry": str(registry),
        "repo_root": str(repo.resolve()),
    }


def registry_status(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "registry": str(registry),
        "project_count": len(value["projects"]),
        "projects": value["projects"],
    }


def _registration_for_event(registry: Path, cwd: Path, harness: str) -> tuple[dict[str, Any], str, str] | None:
    candidates: list[tuple[int, int, dict[str, Any], str, str]] = []
    for item in _read_registry(registry)["projects"]:
        if not item.get("enabled", False) or harness not in item.get("harnesses", []):
            continue
        if _is_within(cwd, item["repo_root"]):
            root = str(item["repo_root"])
            candidates.append((2, len(_path_key(root)), item, "repository", root))
        for workspace_root in item.get("workspace_roots", []):
            if _is_within(cwd, workspace_root):
                candidates.append((1, len(_path_key(workspace_root)), item, "workspace", str(workspace_root)))
    if not candidates:
        return None
    best = max(candidates, key=lambda value: (value[0], value[1]))
    tied = [value for value in candidates if value[:2] == best[:2] and value[2]["registration_id"] != best[2]["registration_id"]]
    if tied:
        raise CkbError(f"automation event cwd matches multiple registrations at the same priority: {cwd}")
    return best[2], best[3], best[4]


def _walk_values(value: Any) -> Iterator[tuple[str | None, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield str(key), child
            yield from _walk_values(child)
    elif isinstance(value, list):
        for child in value:
            yield None, child
            yield from _walk_values(child)


def _first_scalar(value: Any, keys: set[str]) -> str | None:
    lowered = {key.casefold() for key in keys}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).casefold() in lowered and isinstance(child, (str, int)):
                text = str(child).strip()
                if text:
                    return text
        for child in value.values():
            found = _first_scalar(child, keys)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _first_scalar(child, keys)
            if found:
                return found
    return None


def _text_content(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_text_content(item) for item in value]
        return "\n".join(item for item in parts if item)
    if isinstance(value, dict):
        direct = value.get("text")
        if isinstance(direct, str):
            return direct
        for key in ("content", "parts", "message", "delta", "info", "properties", "data"):
            if key in value:
                text = _text_content(value[key])
                if text:
                    return text
    return ""


def _event_name(raw: dict[str, Any]) -> str:
    for key in ("hook_event_name", "canonical_type", "event_type", "type"):
        value = raw.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    event = raw.get("event")
    if isinstance(event, dict) and isinstance(event.get("type"), str):
        return event["type"]
    return "unknown"


def _message_role(raw: dict[str, Any]) -> str:
    return (_first_scalar(raw, {"role"}) or "").casefold()


def _normalized_skill_name(value: Any) -> str:
    text = str(value or "").strip().casefold()
    return text.removeprefix("[").removesuffix("]").lstrip("$/").strip()


def _skill_name(raw: dict[str, Any], tool_name: str | None = None, tool_input: Any = None) -> str | None:
    for key, value in _walk_values(raw):
        if not key or key.casefold() not in _SKILL_METADATA_KEYS:
            continue
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, dict):
                item = item.get("name") or item.get("skill") or item.get("skill_name")
            if _normalized_skill_name(item) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    if str(tool_name or "").casefold() == "skill" and isinstance(tool_input, dict):
        for key in ("skill", "name", "skill_name", "command"):
            if _normalized_skill_name(tool_input.get(key)) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "")
    if _SKILL_PROMPT.search(prompt):
        return REQUIRED_SKILL
    return None


def _canonical_type(raw: dict[str, Any], name: str) -> str:
    if name in CANONICAL_EVENTS:
        return name
    normalized = name.casefold()
    mapping = {
        "skillapplied": "skill.applied",
        "skill.applied": "skill.applied",
        "userpromptexpansion": "skill.applied",
        "sessionstart": "session.start",
        "session.created": "session.start",
        "userpromptsubmit": "turn.prompt",
        "assistantmessage": "turn.assistant",
        "posttooluse": "tool.result",
        "posttoolusefailure": "tool.result",
        "tool.execute.after": "tool.result",
        "aftertool": "tool.result",
        "filechanged": "file.changed",
        "file.edited": "file.changed",
        "afterfileedit": "file.changed",
        "stop": "turn.stop",
        "afteragent": "turn.stop",
        "agentstop": "turn.stop",
        "stopfailure": "turn.stop",
        "session.idle": "turn.stop",
        "session.execution.succeeded.1": "turn.stop",
        "session.execution.failed.1": "turn.stop",
        "precompact": "compact.before",
        "precompress": "compact.before",
        "postcompact": "compact.after",
        "session.compacted": "compact.after",
        "sessionend": "session.end",
        "session.deleted": "session.end",
        "beforeagent": "turn.prompt",
        "beforesubmitprompt": "turn.prompt",
        "userpromptsubmitted": "turn.prompt",
        "afteragentresponse": "turn.assistant",
    }
    if normalized == "pretooluse":
        tool_name = _first_scalar(raw, {"tool_name", "tool", "toolName"})
        return "skill.applied" if str(tool_name or "").casefold() == "skill" else ""
    if normalized == "message.updated":
        return "turn.prompt" if _message_role(raw) == "user" else "turn.assistant"
    return mapping.get(normalized, "")


def _extract_paths(value: Any) -> list[str]:
    result: list[str] = []
    for key, child in _walk_values(value):
        if key and key.casefold() in _PATH_KEYS:
            if isinstance(child, str):
                result.append(child)
            elif isinstance(child, list):
                result.extend(str(item) for item in child if isinstance(item, (str, Path)))
        if isinstance(child, str):
            result.extend(match.strip() for match in _PATCH_PATH.findall(child))
    return list(dict.fromkeys(path.strip() for path in result if path.strip()))


def normalize_event(harness: str, raw: dict[str, Any]) -> dict[str, Any]:
    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported automation harness: {harness}")
    if not isinstance(raw, dict):
        raise CkbError("automation event must be one JSON object")
    name = _event_name(raw)
    canonical = _canonical_type(raw, name)
    if not canonical:
        raise CkbError(f"unsupported automation event for {harness}: {name}")
    session_id = _first_scalar(
        raw,
        {"session_id", "sessionid", "sessionId", "session", "conversation_id", "conversationId", "composer_id"},
    ) or "session-unknown"
    turn_id = _first_scalar(raw, {"turn_id", "turnid", "turnId"})
    tool_use_id = _first_scalar(raw, {"tool_use_id", "tooluseid", "toolUseId", "toolCallID", "callID"})
    cwd = _first_scalar(raw, {"cwd", "directory", "worktree", "project_dir", "projectDir"}) or os.getcwd()
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "").strip()
    assistant = str(
        raw.get("last_assistant_message")
        or raw.get("assistant_message")
        or raw.get("prompt_response")
        or raw.get("response")
        or raw.get("delta")
        or ""
    ).strip()
    if canonical in {"turn.prompt", "turn.assistant"} and not (prompt or assistant):
        text = _text_content(raw.get("message") or raw.get("info") or raw.get("properties") or raw)
        if canonical == "turn.prompt":
            prompt = text.strip()
        else:
            assistant = text.strip()
    tool_name = _first_scalar(raw, {"tool_name", "tool", "toolName"})
    tool_input = raw.get("tool_input", raw.get("toolArgs", raw.get("input")))
    tool_output = raw.get(
        "tool_response",
        raw.get("tool_result", raw.get("toolResult", raw.get("tool_output", raw.get("output", raw.get("result"))))),
    )
    failed_names = {"posttoolusefailure", "stopfailure", "session.execution.failed.1"}
    event_status = str(raw.get("status") or ("error" if name.casefold() in failed_names else "completed"))
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "harness": harness,
        "event_name": name,
        "canonical_type": canonical,
        "external_event_id": _first_scalar(raw, {"event_id", "eventId", "idempotency_key"}),
        "session_id": session_id,
        "turn_id": turn_id,
        "tool_use_id": tool_use_id,
        "cwd": cwd,
        "prompt": prompt,
        "assistant_message": assistant,
        "tool_name": tool_name,
        "tool_input": tool_input,
        "tool_output": tool_output,
        "tool_status": event_status,
        "skill_name": _skill_name(raw, tool_name, tool_input),
        "changed_paths": _extract_paths(raw),
        "source": raw.get("source") or raw.get("reason") or raw.get("trigger"),
        "received_at_utc": utc_now(),
        "raw": raw,
    }


def _redact_text(text: str, custom: list[re.Pattern[str]], max_chars: int) -> tuple[str, list[str]]:
    types: list[str] = []
    result = text
    for name, pattern in _DEFAULT_STRING_REDACTIONS:
        if pattern.search(result):
            types.append(name)
            if name == "credential-assignment":
                result = pattern.sub(lambda match: f"{match.group(1)}{match.group(2)}[REDACTED:CREDENTIAL]", result)
            else:
                result = pattern.sub(f"[REDACTED:{name.upper()}]", result)
    for index, pattern in enumerate(custom, 1):
        if pattern.search(result):
            types.append(f"custom-{index}")
            result = pattern.sub(f"[REDACTED:CUSTOM-{index}]", result)
    encoded = result.encode("utf-8")
    if len(encoded) > max_chars:
        data = encoded[:max_chars]
        while True:
            try:
                result = data.decode("utf-8") + f"\n[TRUNCATED:{len(encoded) - len(data)}-BYTES]"
                break
            except UnicodeDecodeError as exc:
                data = data[: exc.start]
        types.append("size-limit")
    return result, types


def redact_event(event: dict[str, Any], custom_patterns: list[str], max_chars: int) -> dict[str, Any]:
    custom = [re.compile(pattern) for pattern in custom_patterns]
    redaction_types: list[str] = []

    def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

    result = redact(event)
    result["redaction_count"] = len(redaction_types)
    result["redaction_types"] = sorted(set(redaction_types))
    return result


def _automation_root(output: Path) -> Path:
    root = output / "workspace-meta" / "automation"
    for relative in ("spool/pending", "spool/processed", "spool/failed", "pending-reviews"):
        (root / relative).mkdir(parents=True, exist_ok=True)
    return root


def initialize_automation_database(output: Path) -> Path:
    output = output.resolve()
    path = output / AUTOMATION_DATABASE
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path, timeout=10)
    try:
        connection.execute("PRAGMA journal_mode=WAL")
        connection.execute("PRAGMA busy_timeout=10000")
        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS sessions(
                session_key TEXT PRIMARY KEY,
                harness TEXT NOT NULL,
                external_session_id TEXT NOT NULL,
                repo_root TEXT NOT NULL,
                status TEXT NOT NULL,
                started_at_utc TEXT,
                ended_at_utc TEXT,
                first_prompt TEXT NOT NULL DEFAULT '',
                last_assistant_message TEXT NOT NULL DEFAULT '',
                turn_count INTEGER NOT NULL DEFAULT 0,
                baseline_paths_json TEXT NOT NULL DEFAULT '[]',
                baseline_state_json TEXT NOT NULL DEFAULT '{}',
                UNIQUE(harness, external_session_id, repo_root)
            );
            CREATE TABLE IF NOT EXISTS skill_activations(
                activation_key TEXT PRIMARY KEY,
                harness TEXT NOT NULL,
                external_session_id TEXT NOT NULL,
                repo_root TEXT NOT NULL,
                skill_name TEXT NOT NULL,
                activation_source TEXT NOT NULL,
                activated_at_utc TEXT NOT NULL,
                UNIQUE(harness, external_session_id, repo_root, skill_name)
            );
            CREATE TABLE IF NOT EXISTS turns(
                turn_key TEXT PRIMARY KEY,
                session_key TEXT NOT NULL REFERENCES sessions(session_key),
                external_turn_id TEXT NOT NULL,
                ordinal INTEGER NOT NULL,
                status TEXT NOT NULL,
                prompt TEXT NOT NULL DEFAULT '',
                assistant_message TEXT NOT NULL DEFAULT '',
                started_at_utc TEXT,
                completed_at_utc TEXT,
                UNIQUE(session_key, external_turn_id),
                UNIQUE(session_key, ordinal)
            );
            CREATE TABLE IF NOT EXISTS events(
                event_id TEXT PRIMARY KEY,
                harness TEXT NOT NULL,
                event_name TEXT NOT NULL,
                canonical_type TEXT NOT NULL,
                session_key TEXT NOT NULL REFERENCES sessions(session_key),
                turn_key TEXT REFERENCES turns(turn_key),
                tool_use_id TEXT,
                cwd TEXT NOT NULL,
                received_at_utc TEXT NOT NULL,
                redaction_count INTEGER NOT NULL,
                payload_json TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS events_session ON events(session_key, received_at_utc);
            CREATE TABLE IF NOT EXISTS tool_events(
                event_id TEXT PRIMARY KEY REFERENCES events(event_id),
                session_key TEXT NOT NULL REFERENCES sessions(session_key),
                turn_key TEXT REFERENCES turns(turn_key),
                tool_name TEXT,
                status TEXT NOT NULL,
                changed_paths_json TEXT NOT NULL,
                detail_json TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS changed_paths(
                session_key TEXT NOT NULL REFERENCES sessions(session_key),
                path TEXT NOT NULL,
                first_event_id TEXT NOT NULL,
                last_event_id TEXT NOT NULL,
                change_count INTEGER NOT NULL,
                PRIMARY KEY(session_key, path)
            );
            CREATE TABLE IF NOT EXISTS pending_reviews(
                review_id TEXT PRIMARY KEY,
                session_key TEXT NOT NULL REFERENCES sessions(session_key),
                turn_key TEXT NOT NULL REFERENCES turns(turn_key),
                kind TEXT NOT NULL,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                changed_paths_json TEXT NOT NULL,
                status TEXT NOT NULL,
                evidence_json TEXT NOT NULL,
                created_at_utc TEXT NOT NULL,
                reviewed_at_utc TEXT,
                human_file TEXT,
                UNIQUE(turn_key)
            );
            CREATE VIRTUAL TABLE IF NOT EXISTS automation_fts USING fts5(
                review_id UNINDEXED,
                title,
                content,
                changed_paths,
                tokenize='trigram'
            );
            """
        )
        session_columns = {row[1] for row in connection.execute("PRAGMA table_info(sessions)")}
        if "baseline_state_json" not in session_columns:
            connection.execute("ALTER TABLE sessions ADD COLUMN baseline_state_json TEXT NOT NULL DEFAULT '{}'")
        connection.execute("INSERT OR REPLACE INTO meta VALUES('schema_version',?)", (str(AUTOMATION_SCHEMA_VERSION),))
        connection.commit()
    finally:
        connection.close()
    _automation_root(output)
    return path


def _git_status_paths(repo: Path) -> list[str]:
    prefix_result = run(["git", "rev-parse", "--show-prefix"], cwd=repo)
    prefix = prefix_result.stdout.strip().replace("\\", "/") if prefix_result.returncode == 0 else ""
    completed = run(["git", "status", "--porcelain=v1", "-z", "--untracked-files=all", "--", "."], cwd=repo)
    if completed.returncode:
        return []
    values: list[str] = []
    for record in completed.stdout.split("\0"):
        if len(record) < 4:
            continue
        path = record[3:].strip()
        if " -> " in path:
            path = path.rsplit(" -> ", 1)[1]
        if path:
            path = path.replace("\\", "/")
            if prefix and path.startswith(prefix):
                path = path[len(prefix) :]
            path = path.removeprefix("./")
            if path and _change_path_allowed(path):
                values.append(path)
    return sorted(set(values))


def _change_path_allowed(relative: str) -> bool:
    path = Path(relative.replace("\\", "/"))
    return not any(part.casefold() in _IGNORED_CHANGE_PARTS for part in path.parts) and path.suffix.casefold() not in _IGNORED_CHANGE_SUFFIXES


def _working_file_state(repo: Path, paths: list[str]) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for relative in paths:
        path = repo / relative
        if not path.is_file():
            result[relative] = {"exists": False, "size": 0, "content_sha256": None}
            continue
        digest = hashlib.sha256()
        try:
            with path.open("rb") as handle:
                for block in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(block)
            result[relative] = {"exists": True, "size": path.stat().st_size, "content_sha256": digest.hexdigest()}
        except OSError:
            result[relative] = {"exists": path.exists(), "size": -1, "content_sha256": None}
    return result


def _relative_changed_paths(paths: list[str], repo: Path, output: Path, event_cwd: Path | None = None) -> list[str]:
    result: list[str] = []
    for value in paths:
        candidate = Path(value)
        candidates = [candidate] if candidate.is_absolute() else [*([] if event_cwd is None else [event_cwd / candidate]), repo / candidate]
        for possible in candidates:
            if (
                not candidate.is_absolute()
                and event_cwd is not None
                and not _is_within(event_cwd, repo)
                and possible == repo / candidate
                and not possible.exists()
                and run(["git", "ls-files", "--error-unmatch", "--", candidate.as_posix()], cwd=repo).returncode != 0
            ):
                # A workspace-level relative path that is neither present nor
                # tracked in the source repository belongs to scratch/output,
                # not to an imaginary path with the same spelling under repo.
                continue
            try:
                resolved = possible.resolve()
            except OSError:
                continue
            if not _is_within(resolved, repo) or _is_within(resolved, output):
                continue
            try:
                relative = resolved.relative_to(repo.resolve()).as_posix()
            except ValueError:
                continue
            if relative and relative != "." and _change_path_allowed(relative):
                result.append(relative)
                break
    return sorted(set(result))


@contextmanager
def _drain_lock(output: Path, timeout: float = 3.0) -> Iterator[bool]:
    root = _automation_root(output)
    lock = root / "drain.lock"
    deadline = time.monotonic() + timeout
    acquired = False
    while time.monotonic() < deadline:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
            os.close(descriptor)
            acquired = True
            break
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink()
                    continue
            except FileNotFoundError:
                continue
            time.sleep(0.05)
    try:
        yield acquired
    finally:
        if acquired:
            try:
                lock.unlink()
            except FileNotFoundError:
                pass


def enqueue_event(output: Path, event: dict[str, Any]) -> Path:
    pending = _automation_root(output) / "spool" / "pending"
    name = f"{time.time_ns():020d}-{os.getpid()}-{uuid.uuid4().hex}.json"
    path = pending / name
    temporary = path.with_suffix(".tmp")
    temporary.write_text(json.dumps(event, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    os.replace(temporary, path)
    return path


def _spool_events(directory: Path) -> list[Path]:
    return sorted(path for path in directory.glob("*.json") if not path.name.endswith(".error.json"))


def _session_key(event: dict[str, Any], repo: Path) -> str:
    return stable_id("autosession", event["harness"], event["session_id"], _path_key(repo))


def default_session_id(harness: str) -> str | None:
    for key in ("CKB_SESSION_ID", *_SESSION_ENVIRONMENT.get(harness, ())):
        value = os.environ.get(key)
        if value and value.strip():
            return value.strip()
    return None


def _activation_key(harness: str, session_id: str, repo: Path) -> str:
    return stable_id("skillactivation", harness, session_id, _path_key(repo), REQUIRED_SKILL)


def _record_skill_activation(
    output: Path,
    repo: Path,
    harness: str,
    session_id: str,
    source: str,
) -> dict[str, Any]:
    path = initialize_automation_database(output)
    key = _activation_key(harness, session_id, repo)
    connection = sqlite3.connect(path, timeout=10)
    try:
        existing = connection.execute("SELECT activated_at_utc,activation_source FROM skill_activations WHERE activation_key=?", (key,)).fetchone()
        if existing is None:
            activated_at = utc_now()
            connection.execute(
                "INSERT INTO skill_activations VALUES(?,?,?,?,?,?,?)",
                (key, harness, session_id, str(repo), REQUIRED_SKILL, source, activated_at),
            )
            connection.commit()
            status = "activated"
            activation_source = source
        else:
            activated_at = str(existing[0])
            activation_source = str(existing[1])
            status = "already-activated"
    finally:
        connection.close()
    return {
        "status": status,
        "activation_key": key,
        "harness": harness,
        "session_id": session_id,
        "repo_root": str(repo),
        "knowledge_output": str(output),
        "skill_name": REQUIRED_SKILL,
        "activation_source": activation_source,
        "activated_at_utc": activated_at,
    }


def _skill_activation(output: Path, repo: Path, harness: str, session_id: str) -> dict[str, Any] | None:
    path = output / AUTOMATION_DATABASE
    if not path.is_file():
        path = initialize_automation_database(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute(
            "SELECT activation_key,activation_source,activated_at_utc FROM skill_activations WHERE harness=? AND external_session_id=? AND repo_root=? AND skill_name=?",
            (harness, session_id, str(repo), REQUIRED_SKILL),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return None
    return {"activation_key": row[0], "activation_source": row[1], "activated_at_utc": row[2]}


def activate_skill_session(
    harness: str,
    session_id: str | None,
    cwd: Path,
    registry_path: Path | None = None,
    source: str = "agent-skill-start",
) -> dict[str, Any]:
    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported automation harness: {harness}")
    resolved_session = str(session_id or default_session_id(harness) or "").strip()
    if not resolved_session:
        raise CkbError(f"automation activation requires --session-id or a {harness} session environment variable")
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    event_cwd = cwd.expanduser().resolve()
    matched = _registration_for_event(registry, event_cwd, harness)
    if matched is None:
        return {
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "status": "ignored",
            "reason": "project-not-registered-for-harness",
            "harness": harness,
            "session_id": resolved_session,
            "cwd": str(event_cwd),
        }
    registration, match_kind, matched_root = matched
    output = Path(registration["knowledge_output"]).resolve()
    repo = Path(registration["repo_root"]).resolve()
    activation = _record_skill_activation(output, repo, harness, resolved_session, source)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        **activation,
        "registration_match": {"kind": match_kind, "root": matched_root},
    }


def _explicit_skill_application(event: dict[str, Any]) -> str | None:
    if event.get("skill_name") == REQUIRED_SKILL:
        if event["canonical_type"] == "skill.applied":
            return "native-skill-event"
        raw = event.get("raw") or {}
        if raw.get("ckb_skill_applied") is True:
            return "explicit-payload-field"
        if _SKILL_PROMPT.search(str(event.get("prompt") or "")):
            return "explicit-prompt-invocation"
        return "harness-skill-metadata"
    return None


def _ensure_session(
    connection: sqlite3.Connection,
    event: dict[str, Any],
    repo: Path,
    output: Path,
) -> str:
    key = _session_key(event, repo)
    existing = connection.execute("SELECT 1 FROM sessions WHERE session_key=?", (key,)).fetchone()
    if existing is None:
        baseline = _git_status_paths(repo) if event["canonical_type"] in {"session.start", "skill.applied"} or event.get("skill_activation") else []
        baseline_state = _working_file_state(repo, baseline)
        connection.execute(
            "INSERT INTO sessions(session_key,harness,external_session_id,repo_root,status,started_at_utc,baseline_paths_json,baseline_state_json) VALUES(?,?,?,?,?,?,?,?)",
            (
                key,
                event["harness"],
                event["session_id"],
                str(repo),
                "active",
                event["received_at_utc"],
                json.dumps(baseline, ensure_ascii=False),
                json.dumps(baseline_state, ensure_ascii=False, sort_keys=True),
            ),
        )
    if event["canonical_type"] in {"session.start", "skill.applied"}:
        connection.execute(
            "UPDATE sessions SET status='active',started_at_utc=COALESCE(started_at_utc,?) WHERE session_key=?",
            (event["received_at_utc"], key),
        )
    return key


def _resolve_turn(
    connection: sqlite3.Connection,
    event: dict[str, Any],
    session_key: str,
) -> tuple[str | None, str | None]:
    canonical = event["canonical_type"]
    if canonical in {"skill.applied", "session.start", "session.end"}:
        return None, None
    supplied = event.get("turn_id")
    if supplied:
        external = str(supplied)
        row = connection.execute("SELECT turn_key FROM turns WHERE session_key=? AND external_turn_id=?", (session_key, external)).fetchone()
        if row:
            return str(row[0]), external
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    active = connection.execute(
        "SELECT turn_key,external_turn_id,prompt FROM turns WHERE session_key=? AND status='active' ORDER BY ordinal DESC LIMIT 1",
        (session_key,),
    ).fetchone()
    if canonical == "turn.prompt":
        prompt = event.get("prompt") or ""
        if active and str(active[2]) == prompt:
            return str(active[0]), str(active[1])
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        external = f"turn-{ordinal:06d}"
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    if active:
        return str(active[0]), str(active[1])
    if canonical in {"turn.assistant", "turn.stop", "compact.before", "compact.after"}:
        latest = connection.execute(
            "SELECT turn_key,external_turn_id FROM turns WHERE session_key=? ORDER BY ordinal DESC LIMIT 1",
            (session_key,),
        ).fetchone()
        if latest:
            return str(latest[0]), str(latest[1])
    ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
    external = f"turn-{ordinal:06d}"
    key = stable_id("autoturn", session_key, external)
    connection.execute(
        "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
        (key, session_key, external, ordinal, "active", event["received_at_utc"]),
    )
    return key, external


def _event_id(event: dict[str, Any], session_key: str, turn_key: str | None) -> str:
    explicit = event.get("external_event_id")
    if explicit:
        return stable_id("autoevent", event["harness"], explicit)
    identity_payload = {
        "canonical_type": event["canonical_type"],
        "prompt": event.get("prompt") or "",
        "assistant_message": event.get("assistant_message") or "",
        "tool_name": event.get("tool_name"),
        "tool_use_id": event.get("tool_use_id"),
        "changed_paths": event.get("changed_paths") or [],
        "source": event.get("source"),
    }
    return stable_id(
        "autoevent",
        event["harness"],
        session_key,
        turn_key or "session",
        event["canonical_type"],
        event.get("tool_use_id") or "",
        json.dumps(identity_payload, ensure_ascii=False, sort_keys=True),
    )


def _pending_review_content(
    event: dict[str, Any],
    turn: sqlite3.Row,
    changed_paths: list[str],
) -> str:
    prompt = str(turn["prompt"] or "（本轮没有可用的用户消息。）")
    assistant = str(turn["assistant_message"] or event.get("assistant_message") or "（本轮没有可用的最终回答。）")
    path_lines = [f"- `{path}`" for path in changed_paths] or ["- 本轮没有检测到项目文件变化。"]
    return "\n".join(
        [
            "## 用户请求",
            "",
            prompt,
            "",
            "## Agent 最终回答",
            "",
            assistant,
            "",
            "## 修改证据",
            "",
            *path_lines,
            "",
            "## 审阅要求",
            "",
            "本页是机器层待审阅记录。Agent 需要重新核对关联源码和验证证据，使用简体中文确认修改内容、修改原因与验证结果后，才可晋升到人类知识库。",
        ]
    ).rstrip() + "\n"


def _create_pending_review(
    connection: sqlite3.Connection,
    output: Path,
    repo: Path,
    event: dict[str, Any],
    session_key: str,
    turn_key: str | None,
) -> str | None:
    if not turn_key:
        return None
    existing = connection.execute("SELECT review_id FROM pending_reviews WHERE turn_key=?", (turn_key,)).fetchone()
    if existing:
        return str(existing[0])
    turn = connection.execute("SELECT * FROM turns WHERE turn_key=?", (turn_key,)).fetchone()
    session = connection.execute("SELECT * FROM sessions WHERE session_key=?", (session_key,)).fetchone()
    if turn is None or session is None:
        return None
    recorded = [row[0] for row in connection.execute("SELECT path FROM changed_paths WHERE session_key=? ORDER BY path", (session_key,))]
    baseline = set(json.loads(session["baseline_paths_json"] or "[]"))
    baseline_state = json.loads(session["baseline_state_json"] or "{}")
    current = set(_git_status_paths(repo))
    current_state = _working_file_state(repo, sorted(current & baseline))
    changed_from_dirty_baseline = {
        path for path in current & baseline if current_state.get(path) != baseline_state.get(path)
    }
    changed_paths = sorted(set(recorded) | (current - baseline) | changed_from_dirty_baseline)
    content = _pending_review_content(event, turn, changed_paths)
    kind = "change" if changed_paths else "session"
    review_id = stable_id("autoreview", turn_key)
    title = f"{event['harness']} 会话第 {turn['ordinal']} 轮待审阅"
    evidence = {
        "harness": event["harness"],
        "external_session_id": event["session_id"],
        "external_turn_id": turn["external_turn_id"],
        "event_name": event["event_name"],
        "redaction_count": event.get("redaction_count", 0),
    }
    connection.execute(
        "INSERT INTO pending_reviews VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            review_id,
            session_key,
            turn_key,
            kind,
            title,
            content,
            json.dumps(changed_paths, ensure_ascii=False),
            "pending-agent-review",
            json.dumps(evidence, ensure_ascii=False, sort_keys=True),
            event["received_at_utc"],
            None,
            None,
        ),
    )
    connection.execute("INSERT INTO automation_fts VALUES(?,?,?,?)", (review_id, title, content, " ".join(changed_paths)))
    sidecar = _automation_root(output) / "pending-reviews"
    body_path = sidecar / f"{review_id}.md"
    record_path = sidecar / f"{review_id}.json"
    body_path.write_text(content, encoding="utf-8", newline="\n")
    json_write(
        record_path,
        {
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "review_id": review_id,
            "status": "pending-agent-review",
            "kind": kind,
            "title": title,
            "body": str(body_path.resolve()),
            "changed_paths": changed_paths,
            "evidence": evidence,
            "created_at_utc": event["received_at_utc"],
        },
    )
    return review_id


def _process_event(
    connection: sqlite3.Connection,
    output: Path,
    repo: Path,
    event: dict[str, Any],
) -> dict[str, Any]:
    connection.row_factory = sqlite3.Row
    session_key = _ensure_session(connection, event, repo, output)
    turn_key, external_turn_id = _resolve_turn(connection, event, session_key)
    event_id = _event_id(event, session_key, turn_key)
    if connection.execute("SELECT 1 FROM events WHERE event_id=?", (event_id,)).fetchone():
        return {"status": "duplicate", "event_id": event_id, "session_key": session_key, "turn_key": turn_key}
    payload = json.dumps(event, ensure_ascii=False, sort_keys=True)
    connection.execute(
        "INSERT INTO events VALUES(?,?,?,?,?,?,?,?,?,?,?)",
        (
            event_id,
            event["harness"],
            event["event_name"],
            event["canonical_type"],
            session_key,
            turn_key,
            event.get("tool_use_id"),
            event["cwd"],
            event["received_at_utc"],
            int(event.get("redaction_count", 0)),
            payload,
        ),
    )
    canonical = event["canonical_type"]
    if canonical == "turn.prompt" and turn_key:
        connection.execute(
            "UPDATE turns SET prompt=?,status='active',started_at_utc=COALESCE(started_at_utc,?) WHERE turn_key=?",
            (event.get("prompt") or "", event["received_at_utc"], turn_key),
        )
        connection.execute(
            "UPDATE sessions SET first_prompt=CASE WHEN first_prompt='' THEN ? ELSE first_prompt END WHERE session_key=?",
            (event.get("prompt") or "", session_key),
        )
    elif canonical == "turn.assistant" and turn_key:
        connection.execute("UPDATE turns SET assistant_message=? WHERE turn_key=?", (event.get("assistant_message") or "", turn_key))
        connection.execute("UPDATE sessions SET last_assistant_message=? WHERE session_key=?", (event.get("assistant_message") or "", session_key))
    if canonical in {"tool.result", "file.changed"}:
        paths = _relative_changed_paths(
            event.get("changed_paths") or [],
            repo,
            output,
            Path(str(event.get("cwd") or repo)).expanduser(),
        )
        connection.execute(
            "INSERT INTO tool_events VALUES(?,?,?,?,?,?,?)",
            (event_id, session_key, turn_key, event.get("tool_name"), event.get("tool_status") or "completed", json.dumps(paths, ensure_ascii=False), payload),
        )
        for path in paths:
            connection.execute(
                "INSERT INTO changed_paths VALUES(?,?,?,?,1) ON CONFLICT(session_key,path) DO UPDATE SET last_event_id=excluded.last_event_id,change_count=changed_paths.change_count+1",
                (session_key, path, event_id, event_id),
            )
    review_id = None
    if canonical == "turn.stop" and turn_key:
        assistant = event.get("assistant_message") or ""
        if assistant:
            connection.execute("UPDATE turns SET assistant_message=? WHERE turn_key=?", (assistant, turn_key))
            connection.execute("UPDATE sessions SET last_assistant_message=? WHERE session_key=?", (assistant, session_key))
        connection.execute("UPDATE turns SET status='complete',completed_at_utc=? WHERE turn_key=?", (event["received_at_utc"], turn_key))
        connection.execute(
            "UPDATE sessions SET turn_count=(SELECT count(*) FROM turns WHERE session_key=? AND status='complete') WHERE session_key=?",
            (session_key, session_key),
        )
        review_id = _create_pending_review(connection, output, repo, event, session_key, turn_key)
    elif canonical == "session.end":
        active = connection.execute(
            "SELECT turn_key FROM turns WHERE session_key=? AND status='active' ORDER BY ordinal DESC LIMIT 1",
            (session_key,),
        ).fetchone()
        if active:
            connection.execute("UPDATE turns SET status='complete',completed_at_utc=? WHERE turn_key=?", (event["received_at_utc"], active[0]))
            review_id = _create_pending_review(connection, output, repo, event, session_key, str(active[0]))
        connection.execute("UPDATE sessions SET status='complete',ended_at_utc=? WHERE session_key=?", (event["received_at_utc"], session_key))
    return {
        "status": "recorded",
        "event_id": event_id,
        "session_key": session_key,
        "turn_key": turn_key,
        "external_turn_id": external_turn_id,
        "review_id": review_id,
    }


def drain_automation(output: Path, limit: int = 500) -> dict[str, Any]:
    output = output.resolve()
    initialize_automation_database(output)
    root = _automation_root(output)
    pending = root / "spool" / "pending"
    processed = root / "spool" / "processed"
    failed = root / "spool" / "failed"
    results: list[dict[str, Any]] = []
    with _drain_lock(output) as acquired:
        if not acquired:
            return {"schema_version": AUTOMATION_SCHEMA_VERSION, "status": "queued", "reason": "drain-lock-busy", "pending": len(_spool_events(pending))}
        connection = sqlite3.connect(output / AUTOMATION_DATABASE, timeout=10)
        try:
            connection.execute("PRAGMA busy_timeout=10000")
            for path in _spool_events(pending)[:limit]:
                try:
                    envelope = json_load(path)
                    event = envelope["event"]
                    repo = Path(envelope["repo_root"]).resolve()
                    connection.execute("BEGIN IMMEDIATE")
                    result = _process_event(connection, output, repo, event)
                    connection.commit()
                    destination = processed / f"{result['event_id']}.json"
                    if destination.exists():
                        path.unlink()
                    else:
                        path.replace(destination)
                    results.append(result)
                except Exception as exc:
                    connection.rollback()
                    destination = failed / path.name
                    if destination.exists():
                        destination = failed / f"{path.stem}-{uuid.uuid4().hex}.json"
                    path.replace(destination)
                    json_write(destination.with_suffix(".error.json"), {"status": "failed", "error": f"{type(exc).__name__}: {exc}"})
                    results.append({"status": "failed", "spool": str(destination), "error": f"{type(exc).__name__}: {exc}"})
        finally:
            connection.close()
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "passed" if not any(item["status"] == "failed" for item in results) else "failed",
        "processed": sum(item["status"] == "recorded" for item in results),
        "duplicates": sum(item["status"] == "duplicate" for item in results),
        "failed": sum(item["status"] == "failed" for item in results),
        "pending": len(_spool_events(pending)),
        "results": results,
    }


def retry_failed_automation(output: Path, limit: int = 500) -> dict[str, Any]:
    output = output.resolve()
    root = _automation_root(output)
    failed = root / "spool" / "failed"
    pending = root / "spool" / "pending"
    moved = 0
    for path in _spool_events(failed)[:limit]:
        destination = pending / f"retry-{time.time_ns():020d}-{uuid.uuid4().hex}.json"
        path.replace(destination)
        error = path.with_suffix(".error.json")
        if error.is_file():
            error.unlink()
        moved += 1
    result = drain_automation(output, limit)
    return {"schema_version": AUTOMATION_SCHEMA_VERSION, "status": result["status"], "retried": moved, "drain": result}


def _hook_context(output: Path) -> str:
    status = automation_status(output)
    return (
        "当前会话已明确应用 code-knowledge-builder Skill，CKB 自动同步已激活：本轮事件会先进入脱敏、幂等的机器层队列。"
        f"当前待 Agent 审阅记录 {status['pending_reviews']} 条，失败事件 {status['failed_spool']} 条。"
        "分析和修改结论需使用简体中文核对来源后，再晋升到人类知识库。"
    )


def _hook_output(harness: str, event_name: str, context: str) -> dict[str, Any]:
    if event_name in {"SessionStart", "UserPromptSubmit"} and harness in {"codex", "claude", "dsh"}:
        return {
            "hookSpecificOutput": {
                "hookEventName": event_name,
                "additionalContext": context,
            }
        }
    if harness == "gemini" and event_name in {"SessionStart", "BeforeAgent"}:
        return {"hookSpecificOutput": {"additionalContext": context}}
    if harness == "cursor" and event_name == "sessionStart":
        return {"additional_context": context}
    return {}


def ingest_event(
    harness: str,
    raw: dict[str, Any],
    registry_path: Path | None = None,
) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    normalized = normalize_event(harness, raw)
    cwd = Path(str(normalized["cwd"])).expanduser().resolve()
    matched = _registration_for_event(registry, cwd, harness)
    if matched is None:
        return {
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "status": "ignored",
            "reason": "project-not-registered-for-harness",
            "harness": harness,
            "cwd": str(cwd),
            "hook_output": {},
        }
    registration, match_kind, matched_root = matched
    output = Path(registration["knowledge_output"]).resolve()
    repo = Path(registration["repo_root"]).resolve()
    if not (output / "state.json").is_file():
        raise CkbError(f"registered knowledge output is missing state.json: {output}")
    activation_source = _explicit_skill_application(normalized)
    activation = (
        _record_skill_activation(output, repo, harness, normalized["session_id"], activation_source)
        if activation_source
        else _skill_activation(output, repo, harness, normalized["session_id"])
    )
    if activation is None:
        return {
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "status": "ignored",
            "reason": "skill-not-applied-in-session",
            "required_skill": REQUIRED_SKILL,
            "harness": harness,
            "session_id": normalized["session_id"],
            "cwd": str(cwd),
            "repo_root": str(repo),
            "registration_match": {"kind": match_kind, "root": matched_root},
            "knowledge_output": str(output),
            "hook_output": {},
        }
    redacted = redact_event(normalized, registration.get("custom_redactions", []), int(registration.get("max_field_chars", 12_000)))
    redacted["skill_activation"] = activation
    redacted["registration_match"] = {"kind": match_kind, "root": matched_root}
    spool = enqueue_event(
        output,
        {
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "registration_id": registration["registration_id"],
            "repo_root": str(repo),
            "knowledge_output": str(output),
            "event": redacted,
        },
    )
    drained = drain_automation(output)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "recorded" if drained["processed"] else "duplicate" if drained["duplicates"] else "queued",
        "harness": harness,
        "event_name": normalized["event_name"],
        "canonical_type": normalized["canonical_type"],
        "repo_root": str(repo),
        "registration_match": {"kind": match_kind, "root": matched_root},
        "knowledge_output": str(output),
        "spool": str(spool),
        "redaction_count": redacted["redaction_count"],
        "redaction_types": redacted["redaction_types"],
        "drain": drained,
        "hook_output": _hook_output(harness, normalized["event_name"], _hook_context(output)),
    }


def automation_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    path = initialize_automation_database(output)
    root = _automation_root(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        counts = {
            "skill_activations": connection.execute("SELECT count(*) FROM skill_activations").fetchone()[0],
            "events": connection.execute("SELECT count(*) FROM events").fetchone()[0],
            "sessions": connection.execute("SELECT count(*) FROM sessions").fetchone()[0],
            "active_sessions": connection.execute("SELECT count(*) FROM sessions WHERE status='active'").fetchone()[0],
            "turns": connection.execute("SELECT count(*) FROM turns").fetchone()[0],
            "changed_paths": connection.execute("SELECT count(*) FROM changed_paths").fetchone()[0],
            "pending_reviews": connection.execute("SELECT count(*) FROM pending_reviews WHERE status='pending-agent-review'").fetchone()[0],
            "reviewed": connection.execute("SELECT count(*) FROM pending_reviews WHERE status='agent-reviewed'").fetchone()[0],
        }
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
    finally:
        connection.close()
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready" if integrity == "ok" else "failed",
        "database": str(path),
        **counts,
        "pending_spool": len(_spool_events(root / "spool/pending")),
        "failed_spool": len(_spool_events(root / "spool/failed")),
        "sqlite_integrity": integrity,
    }


def pending_automation_reviews(output: Path, include_reviewed: bool = False) -> dict[str, Any]:
    output = output.resolve()
    path = initialize_automation_database(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        query = "SELECT review_id,kind,title,status,changed_paths_json,created_at_utc,reviewed_at_utc,human_file FROM pending_reviews"
        if not include_reviewed:
            query += " WHERE status='pending-agent-review'"
        query += " ORDER BY created_at_utc,review_id"
        rows = []
        for row in connection.execute(query):
            item = dict(row)
            item["changed_paths"] = json.loads(item.pop("changed_paths_json"))
            rows.append(item)
    finally:
        connection.close()
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "count": len(rows),
        "reviews": rows,
    }


def write_automation_review_template(output: Path, review_id: str, target: Path) -> dict[str, Any]:
    output = output.resolve()
    path = initialize_automation_database(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        row = connection.execute("SELECT * FROM pending_reviews WHERE review_id=?", (review_id,)).fetchone()
    finally:
        connection.close()
    if row is None:
        raise CkbError(f"automation review does not exist: {review_id}")
    changed_paths = json.loads(row["changed_paths_json"])
    template = {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "review_id": review_id,
        "status": "agent-reviewed",
        "kind": row["kind"],
        "title": "填写简洁的中文知识页标题",
        "body": "填写 Agent 重写并核实后的简体中文 Markdown 文件绝对路径",
        "evidence_note": "填写本次审阅如何核对会话、修改范围、源码和验证证据",
        "source_checks": [
            {
                "path": changed,
                "status": "agent-reviewed",
                "evidence_note": "填写重新打开并核对此路径后的中文证据说明",
            }
            for changed in changed_paths
        ],
        "linked_pages": [],
    }
    target = target.resolve()
    if target.exists():
        raise CkbError(f"automation review template already exists: {target}")
    json_write(target, template)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "written",
        "review_id": review_id,
        "template": str(target),
        "changed_paths": changed_paths,
    }


def _heading_errors(text: str, changed: bool) -> list[str]:
    if not changed:
        return []
    headings = {
        re.sub(r"\s+", "", line.lstrip().lstrip("#").strip())
        for line in text.splitlines()
        if line.lstrip().startswith("#")
    }
    return [heading for heading in _CHANGE_HEADINGS if heading not in headings]


def review_automation(output: Path, review_path: Path) -> dict[str, Any]:
    output = output.resolve()
    value = json_load(review_path.resolve())
    if value.get("status") != "agent-reviewed":
        raise CkbError("automation review status must be agent-reviewed")
    review_id = str(value.get("review_id") or "")
    if not review_id:
        raise CkbError("automation review requires review_id")
    body_path = Path(str(value.get("body") or ""))
    if not body_path.is_file():
        raise CkbError(f"automation review body is missing: {body_path}")
    body = body_path.read_text(encoding="utf-8-sig").strip()
    from .machine_knowledge import contains_chinese_narrative

    if not contains_chinese_narrative(body):
        raise CkbError("automation review body must use Simplified Chinese")
    title = str(value.get("title") or "").strip()
    if not title:
        raise CkbError("automation review requires a human-readable title")
    evidence_note = str(value.get("evidence_note") or "").strip()
    if not contains_chinese_narrative(evidence_note):
        raise CkbError("automation review requires a Simplified-Chinese evidence_note")
    path = initialize_automation_database(output)
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    try:
        row = connection.execute("SELECT * FROM pending_reviews WHERE review_id=?", (review_id,)).fetchone()
        if row is None:
            raise CkbError(f"automation review does not exist: {review_id}")
        if row["status"] != "pending-agent-review":
            raise CkbError(f"automation review is not pending: {review_id}; status={row['status']}")
        changed_paths = json.loads(row["changed_paths_json"])
        source_checks = list(value.get("source_checks") or [])
        checked_paths = [str(item.get("path") or "").replace("\\", "/") for item in source_checks]
        if sorted(checked_paths) != sorted(changed_paths):
            raise CkbError(f"automation review source-check set differs from changed paths: expected={changed_paths}; actual={checked_paths}")
        for item in source_checks:
            if item.get("status") != "agent-reviewed" or not contains_chinese_narrative(str(item.get("evidence_note") or "")):
                raise CkbError(f"automation source check requires agent-reviewed Chinese evidence: {item.get('path')}")
        errors = _heading_errors(body, bool(changed_paths))
        if errors:
            raise CkbError(f"changed automation review requires headings: {errors}")
        kind = str(value.get("kind") or row["kind"])
        if kind not in {"analysis", "change", "pitfall", "experiment", "session"}:
            raise CkbError(f"unsupported automation review kind: {kind}")
        from .workspace_notes import record_note, selectors_for_changed_paths

        selectors = list(value.get("linked_pages") or selectors_for_changed_paths(output, changed_paths))
        note = record_note(output, kind, title, body_path, selectors=selectors)
        connection.execute(
            "UPDATE pending_reviews SET status='agent-reviewed',reviewed_at_utc=?,human_file=? WHERE review_id=?",
            (utc_now(), note.get("file"), review_id),
        )
        connection.commit()
    finally:
        connection.close()
    sidecar = _automation_root(output) / "pending-reviews" / f"{review_id}.json"
    record = json_load(sidecar)
    record.update(
        {
            "status": "agent-reviewed",
            "reviewed_at_utc": utc_now(),
            "human_note": note,
            "review_file": str(review_path.resolve()),
            "evidence_note": evidence_note,
            "source_checks": source_checks,
        }
    )
    json_write(sidecar, record)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "agent-reviewed",
        "review_id": review_id,
        "human_note": note,
    }


def search_automation(output: Path, question: str, limit: int = 8) -> list[dict[str, Any]]:
    path = output.resolve() / AUTOMATION_DATABASE
    if not path.is_file():
        return []
    terms = [value for value in re.findall(r"[\w\u3400-\u9fff.-]+", question.casefold()) if len(value) >= 2][:16]
    if not terms:
        return []
    query = " OR ".join('"' + value.replace('"', '""') + '"' for value in terms)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = [
            dict(row)
            for row in connection.execute(
                "SELECT p.review_id,p.title,p.kind,p.status,p.human_file,p.content,p.changed_paths_json,"
                "bm25(automation_fts,0.0,6.0,3.0,2.0) AS rank "
                "FROM automation_fts JOIN pending_reviews p USING(review_id) WHERE automation_fts MATCH ? ORDER BY rank, p.review_id LIMIT ?",
                (query, limit),
            )
        ]
    except sqlite3.OperationalError:
        rows = []
    finally:
        connection.close()
    for row in rows:
        row["changed_paths"] = json.loads(row.pop("changed_paths_json"))
    return rows


def automation_documents(output: Path, kind: str | None = None, limit: int = 20) -> list[dict[str, Any]]:
    path = output.resolve() / AUTOMATION_DATABASE
    if not path.is_file():
        return []
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        query = "SELECT review_id,kind,title,status,human_file,content,changed_paths_json,created_at_utc FROM pending_reviews"
        params: list[Any] = []
        if kind:
            query += " WHERE kind=?"
            params.append(kind)
        query += " ORDER BY created_at_utc DESC,review_id DESC LIMIT ?"
        params.append(limit)
        rows = [dict(row) for row in connection.execute(query, params)]
    finally:
        connection.close()
    for row in rows:
        row["document_id"] = f"automation:{row.pop('review_id')}"
        row["changed_paths"] = json.loads(row.pop("changed_paths_json"))
        row["token_estimate"] = (len(row["content"].encode("utf-8")) + 2) // 3
    return rows

"""Generate host-specific adapters for the CKB automation protocol."""

from __future__ import annotations

import json
from pathlib import Path
import shlex
import subprocess
import sys
from typing import Any

from .automation import SUPPORTED_HARNESSES
from .common import CkbError, json_write


INTEGRATION_VERSION = "1.2.0"


def _looks_windows(path: Path) -> bool:
    text = str(path)
    return (len(text) >= 3 and text[1:3] in {":\\", ":/"}) or text.startswith("\\\\")


def _commands(python: Path, ckb: Path, harness: str, registry: Path) -> tuple[str, str]:
    args = [str(python), "-X", "utf8", str(ckb), "automation", "hook", "--harness", harness, "--registry", str(registry)]
    return shlex.join(args), subprocess.list2cmdline(args)


def _powershell_command(python: Path, ckb: Path, harness: str, registry: Path) -> str:
    def quote(value: Path | str) -> str:
        return "'" + str(value).replace("'", "''") + "'"

    return " ".join(
        [
            "&",
            quote(python),
            "-X",
            "utf8",
            quote(ckb),
            "automation",
            "hook",
            "--harness",
            harness,
            "--registry",
            quote(registry),
        ]
    )


def _handler(posix: str, windows: str, timeout: int, status: str | None = None) -> dict[str, Any]:
    result: dict[str, Any] = {
        "type": "command",
        "command": posix,
        "commandWindows": windows,
        "timeout": timeout,
    }
    if status:
        result["statusMessage"] = status
    return result


def _codex_hooks(posix: str, windows: str, *, dsh_subset: bool = False) -> dict[str, Any]:
    hooks: dict[str, Any] = {
        "SessionStart": [
            {
                "matcher": "startup|resume|clear|compact",
                "hooks": [_handler(posix, windows, 8, "正在恢复 CKB 自动化上下文")],
            }
        ],
        "UserPromptSubmit": [{"hooks": [_handler(posix, windows, 8)]}],
        "PostToolUse": [
            {
                "matcher": "Bash|apply_patch|Edit|Write",
                "hooks": [_handler(posix, windows, 8, "正在记录修改证据")],
            }
        ],
        "Stop": [{"hooks": [_handler(posix, windows, 15, "正在形成机器层待审阅记录")]}],
    }
    if not dsh_subset:
        hooks.update(
            {
                "PreCompact": [{"matcher": "manual|auto", "hooks": [_handler(posix, windows, 8)]}],
                "PostCompact": [{"matcher": "manual|auto", "hooks": [_handler(posix, windows, 8)]}],
                "SessionEnd": [{"hooks": [_handler(posix, windows, 3)]}],
            }
        )
    return {
        "description": "仅在当前会话明确应用 code-knowledge-builder Skill 后，将已登记项目的会话与修改证据同步到机器知识库。",
        "hooks": hooks,
    }


def _claude_hooks(command: str) -> dict[str, Any]:
    def handler(timeout: int) -> dict[str, Any]:
        return {"type": "command", "command": command, "timeout": timeout}

    return {
        "hooks": {
            "SessionStart": [{"matcher": "startup|resume|clear|compact", "hooks": [handler(8)]}],
            "UserPromptSubmit": [{"hooks": [handler(8)]}],
            "UserPromptExpansion": [{"matcher": "code-knowledge-builder", "hooks": [handler(8)]}],
            "PreToolUse": [{"matcher": "Skill", "hooks": [handler(8)]}],
            "PostToolUse": [{"matcher": "Write|Edit|Bash|NotebookEdit", "hooks": [handler(8)]}],
            "PostToolUseFailure": [{"matcher": "Write|Edit|Bash|NotebookEdit", "hooks": [handler(8)]}],
            "FileChanged": [{"hooks": [handler(8)]}],
            "Stop": [{"hooks": [handler(15)]}],
            "StopFailure": [{"hooks": [handler(15)]}],
            "PreCompact": [{"matcher": "manual|auto", "hooks": [handler(8)]}],
            "PostCompact": [{"matcher": "manual|auto", "hooks": [handler(8)]}],
            "SessionEnd": [{"hooks": [handler(3)]}],
        }
    }


def _gemini_hooks(command: str) -> dict[str, Any]:
    def handler(timeout_ms: int) -> dict[str, Any]:
        return {"type": "command", "command": command, "timeout": timeout_ms}

    return {
        "hooks": {
            "SessionStart": [{"matcher": "startup|resume|clear", "hooks": [handler(8_000)]}],
            "BeforeAgent": [{"hooks": [handler(8_000)]}],
            "AfterTool": [{"matcher": ".*", "hooks": [handler(8_000)]}],
            "AfterAgent": [{"hooks": [handler(15_000)]}],
            "PreCompress": [{"hooks": [handler(8_000)]}],
            "SessionEnd": [{"hooks": [handler(3_000)]}],
        }
    }


def _copilot_hooks(posix: str, powershell: str) -> dict[str, Any]:
    def handler(timeout: int, matcher: str | None = None) -> dict[str, Any]:
        value: dict[str, Any] = {
            "type": "command",
            "bash": posix,
            "powershell": powershell,
            "timeoutSec": timeout,
        }
        if matcher:
            value["matcher"] = matcher
        return value

    # PascalCase selects Copilot's VS Code-compatible snake_case payloads,
    # which keeps the adapter aligned with Codex/Claude without pretending the
    # event names or output decisions are otherwise interchangeable.
    return {
        "version": 1,
        "hooks": {
            "SessionStart": [handler(8)],
            "UserPromptSubmit": [handler(8)],
            "PostToolUse": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "PostToolUseFailure": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "Stop": [handler(15)],
            "PreCompact": [handler(8)],
            "SessionEnd": [handler(3)],
        },
    }


def _cursor_hooks(command: str) -> dict[str, Any]:
    def handler(matcher: str | None = None, timeout: int = 8) -> dict[str, Any]:
        value: dict[str, Any] = {"command": command, "timeout": timeout}
        if matcher:
            value["matcher"] = matcher
        return value

    return {
        "version": 1,
        "hooks": {
            "sessionStart": [handler()],
            "beforeSubmitPrompt": [handler("UserPromptSubmit")],
            "postToolUse": [handler("Shell|Write|Delete|MCP:.*")],
            "postToolUseFailure": [handler("Shell|Write|Delete|MCP:.*")],
            "afterFileEdit": [handler("Write")],
            "afterAgentResponse": [handler()],
            "preCompact": [handler()],
            "stop": [handler("Stop", 15)],
            "sessionEnd": [handler(timeout=3)],
        },
    }


def _opencode_stable_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function value(object, keys) {{
  if (!object || typeof object !== "object") return undefined
  for (const key of keys) if (object[key] !== undefined && object[key] !== null) return object[key]
  for (const child of Object.values(object)) {{
    const found = value(child, keys)
    if (found !== undefined) return found
  }}
}}

function text(object) {{
  if (typeof object === "string") return object
  if (Array.isArray(object)) return object.map(text).filter(Boolean).join("\\n")
  if (!object || typeof object !== "object") return ""
  if (typeof object.text === "string") return object.text
  for (const key of ["content", "parts", "message", "delta"]) {{
    const found = text(object[key])
    if (found) return found
  }}
  return ""
}}

function emit(payload) {{
  try {{
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(payload), encoding: "utf8", timeout: 8000, windowsHide: true }})
  }} catch {{}}
}}

export const CodeKnowledgeBuilderSync = async ({{ directory, worktree }}) => {{
  const cwd = worktree || directory || process.cwd()
  const assistants = new Map()
  return {{
    event: async ({{ event }}) => {{
      const data = event?.properties ?? event?.data ?? event ?? {{}}
      const info = data?.info ?? data
      const sessionID = String(value(info, ["sessionID", "sessionId", "session_id", "id"]) ?? "session-unknown")
      const base = {{ session_id: sessionID, cwd }}
      if (event?.type === "session.created") emit({{ ...base, hook_event_name: "SessionStart", source: "startup", event_id: `session-created:${{sessionID}}` }})
      if (event?.type === "message.updated") {{
        const role = String(value(info, ["role"]) ?? "").toLowerCase()
        const body = text(info)
        const messageID = String(value(info, ["messageID", "messageId", "id"]) ?? "")
        if (role === "user") emit({{ ...base, hook_event_name: "UserPromptSubmit", prompt: body, event_id: `message:${{messageID}}` }})
        if (role === "assistant") {{
          assistants.set(sessionID, body)
          emit({{ ...base, hook_event_name: "AssistantMessage", assistant_message: body, event_id: `message:${{messageID}}` }})
        }}
      }}
      if (event?.type === "command.executed") {{
        const commandName = String(value(data, ["command", "commandName", "name"]) ?? "")
        if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ ...base, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
      }}
      if (event?.type === "file.edited") emit({{ ...base, hook_event_name: "FileChanged", file_path: value(data, ["file", "filePath", "path"]), event: "change" }})
      if (event?.type === "session.compacted") emit({{ ...base, hook_event_name: "PostCompact", trigger: "auto" }})
      if (event?.type === "session.idle") emit({{ ...base, hook_event_name: "Stop", last_assistant_message: assistants.get(sessionID) ?? "", stop_hook_active: false }})
      if (event?.type === "session.deleted") emit({{ ...base, hook_event_name: "SessionEnd", reason: "other" }})
    }},
    "tool.execute.after": async (input, output) => {{
      emit({{
        session_id: String(input?.sessionID ?? input?.sessionId ?? "session-unknown"),
        cwd,
        hook_event_name: "PostToolUse",
        tool_name: String(input?.tool ?? "unknown"),
        tool_use_id: String(input?.callID ?? input?.toolCallID ?? input?.id ?? ""),
        tool_input: input?.args ?? input?.input ?? input,
        tool_response: output,
        status: "completed",
      }})
    }},
  }}
}}
'''


def _opencode_v2_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode-v2", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"
import {{ Plugin }} from "@opencode-ai/plugin"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function emit(payload) {{
  try {{ spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(payload), encoding: "utf8", timeout: 8000, windowsHide: true }}) }} catch {{}}
}}

function messageText(message) {{
  const parts = message?.parts ?? message?.content ?? []
  if (typeof parts === "string") return parts
  return Array.isArray(parts) ? parts.map((part) => typeof part === "string" ? part : part?.text ?? "").filter(Boolean).join("\\n") : ""
}}

function unwrapMessages(value) {{
  if (Array.isArray(value)) return value
  if (Array.isArray(value?.data)) return value.data
  if (Array.isArray(value?.messages)) return value.messages
  return []
}}

function eventSessionID(event) {{
  return String(event?.sessionID ?? event?.properties?.sessionID ?? event?.data?.sessionID ?? "session-unknown")
}}

function eventCwd(event) {{
  return String(event?.cwd ?? event?.location?.directory ?? event?.properties?.cwd ?? event?.data?.cwd ?? process.cwd())
}}

export default Plugin.define({{
  id: "code-knowledge-builder.sync",
  setup: async (ctx) => {{
    const seenSessions = new Set()
    await ctx.session.hook("context", (event) => {{
      const sessionID = String(event.sessionID ?? "session-unknown")
      const cwd = eventCwd(event)
      if (!seenSessions.has(sessionID)) {{
        seenSessions.add(sessionID)
        emit({{ session_id: sessionID, cwd, hook_event_name: "SessionStart", source: "startup", event_id: `session:${{sessionID}}` }})
      }}
      const messages = Array.isArray(event.messages) ? event.messages : []
      const latest = [...messages].reverse().find((item) => item?.role === "user")
      if (latest) emit({{ session_id: sessionID, cwd, hook_event_name: "UserPromptSubmit", prompt: messageText(latest), event_id: `message:${{latest.id ?? latest.messageID ?? "latest"}}` }})
    }})
    await ctx.tool.hook("execute.after", (event) => {{
      emit({{
        session_id: String(event.sessionID ?? "session-unknown"),
        cwd: String(event.cwd ?? process.cwd()),
        hook_event_name: "PostToolUse",
        tool_name: String(event.tool ?? "unknown"),
        tool_use_id: String(event.toolCallID ?? event.callID ?? ""),
        tool_input: event.input,
        tool_response: event.status === "error" ? event.error : event.result,
        output_paths: event.outputPaths ?? [],
        status: event.status ?? "completed",
      }})
    }})
    const controller = new AbortController()
    void (async () => {{
      try {{
        for await (const event of ctx.event.subscribe({{ signal: controller.signal }})) {{
          const sessionID = eventSessionID(event)
          const cwd = eventCwd(event)
          if (event.type === "command.executed") {{
            const commandName = String(event?.command ?? event?.properties?.command ?? event?.data?.command ?? "")
            if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ session_id: sessionID, cwd, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
          }}
          if (["session.execution.succeeded", "session.execution.succeeded.1", "session.idle"].includes(event.type)) {{
            const messages = unwrapMessages(await ctx.session.context({{ sessionID }}))
            const latest = [...messages].reverse().find((item) => item?.role === "assistant")
            emit({{ session_id: sessionID, cwd, hook_event_name: "Stop", last_assistant_message: messageText(latest), stop_hook_active: false, event_id: `stop:${{sessionID}}:${{latest?.id ?? event.id ?? event.type}}` }})
          }}
          if (["session.execution.failed", "session.execution.failed.1"].includes(event.type)) emit({{ session_id: sessionID, cwd, hook_event_name: "StopFailure", last_assistant_message: String(event.error?.message ?? event.error ?? "OpenCode 执行失败。"), event_id: `stop-failed:${{sessionID}}:${{event.id ?? event.type}}` }})
          if (event.type === "session.deleted") emit({{ session_id: sessionID, cwd, hook_event_name: "SessionEnd", reason: "other", event_id: `session-end:${{sessionID}}` }})
          if (event.type === "session.compacted") emit({{ session_id: sessionID, cwd, hook_event_name: "PostCompact", trigger: "auto", event_id: `compact:${{sessionID}}:${{event.id ?? "auto"}}` }})
        }}
      }} catch {{}}
    }})()
    return () => controller.abort()
  }},
}})
'''


def _generic_schema() -> dict[str, Any]:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "https://code-knowledge-builder.local/automation-event.schema.json",
        "title": "Code Knowledge Builder canonical automation event",
        "type": "object",
        "required": ["canonical_type", "session_id", "cwd"],
        "properties": {
            "canonical_type": {
                "enum": [
                    "skill.applied",
                    "session.start",
                    "turn.prompt",
                    "turn.assistant",
                    "tool.result",
                    "file.changed",
                    "turn.stop",
                    "compact.before",
                    "compact.after",
                    "session.end",
                ]
            },
            "event_id": {"type": "string", "minLength": 1},
            "session_id": {"type": "string", "minLength": 1},
            "turn_id": {"type": "string"},
            "cwd": {"type": "string", "minLength": 1},
            "prompt": {"type": "string"},
            "assistant_message": {"type": "string"},
            "tool_name": {"type": "string"},
            "tool_use_id": {"type": "string"},
            "tool_input": {},
            "tool_output": {},
            "changed_paths": {"type": "array", "items": {"type": "string"}},
            "skill_name": {"type": "string", "const": "code-knowledge-builder"},
            "ckb_skill_applied": {"type": "boolean", "const": True},
        },
        "additionalProperties": True,
    }


def render_integration(
    harness: str,
    destination: Path,
    python: Path | None = None,
    ckb: Path | None = None,
    registry: Path | None = None,
    *,
    force: bool = False,
) -> dict[str, Any]:
    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported integration harness: {harness}")
    destination = destination.resolve()
    python = (python or Path(sys.executable)).expanduser().resolve()
    ckb = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    registry = (registry or Path.home() / ".ckb" / "automation-registry.json").expanduser().resolve()
    if not python.is_file():
        raise CkbError(f"integration Python executable is missing: {python}")
    if not ckb.is_file():
        raise CkbError(f"integration CKB entrypoint is missing: {ckb}")
    if destination.exists() and any(destination.iterdir()) and not force:
        raise CkbError(f"integration destination is not empty: {destination}; use --force to replace generated files")
    destination.mkdir(parents=True, exist_ok=True)
    posix, windows = _commands(python, ckb, harness, registry)
    powershell = _powershell_command(python, ckb, harness, registry)
    files: list[Path] = []

    def write(relative: str, value: str | dict[str, Any]) -> Path:
        path = destination / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(value, ensure_ascii=False, indent=2) + "\n" if isinstance(value, dict) else value
        path.write_text(text, encoding="utf-8", newline="\n")
        files.append(path)
        return path

    if harness == "codex":
        write(
            ".codex-plugin/plugin.json",
            {
                "name": "code-knowledge-builder-sync",
                "version": INTEGRATION_VERSION,
                "description": "仅在会话明确应用 code-knowledge-builder Skill 后，同步已登记项目的 Codex 会话和修改证据。",
                "author": {"name": "Code Knowledge Builder"},
                "interface": {
                    "displayName": "Code Knowledge Builder Sync",
                    "shortDescription": "同步明确应用 CKB Skill 的项目会话",
                    "longDescription": "会话明确应用 code-knowledge-builder Skill 后，把 Codex 生命周期事件写入脱敏机器队列，并等待 Agent 中文审阅后再进入人类知识库。",
                    "developerName": "Code Knowledge Builder",
                    "category": "Productivity",
                    "capabilities": ["Read", "Write"],
                    "defaultPrompt": "检查当前项目的 Code Knowledge Builder 自动同步状态。",
                },
            },
        )
        write("hooks/hooks.json", _codex_hooks(posix, windows))
    elif harness == "claude":
        command = windows if _looks_windows(python) else posix
        write(".claude/settings.json", _claude_hooks(command))
    elif harness == "opencode":
        write(".opencode/plugins/code-knowledge-builder-sync.mjs", _opencode_stable_plugin(python, ckb, registry))
    elif harness == "opencode-v2":
        write(".opencode/plugins/code-knowledge-builder-sync-v2.mjs", _opencode_v2_plugin(python, ckb, registry))
    elif harness == "dsh":
        # The current DSH Codex bridge intentionally reads `command` and ignores
        # Codex's `commandWindows` extension, so stamp the platform command into
        # both fields when rendering on Windows.
        dsh_command = windows if _looks_windows(python) else posix
        write("hooks.json", _codex_hooks(dsh_command, dsh_command, dsh_subset=True))
        config_path = (destination / "hooks.json").as_posix()
        write(
            "cordis.yml.fragment",
            "- dsh-hooks-codex:\n"
            f"    configPath: {json.dumps(config_path)}\n"
            "    model: ckb-sync\n",
        )
    elif harness == "gemini":
        command = windows if _looks_windows(python) else posix
        write(".gemini/settings.json", _gemini_hooks(command))
    elif harness == "copilot":
        write(".github/hooks/code-knowledge-builder.json", _copilot_hooks(posix, powershell))
    elif harness == "cursor":
        command = windows if _looks_windows(python) else posix
        write(".cursor/hooks.json", _cursor_hooks(command))
    else:
        write("automation-event.schema.json", _generic_schema())
        write(
            "example-event.json",
            {
                "canonical_type": "skill.applied",
                "event_id": "HARNESS_EVENT_ID",
                "session_id": "HARNESS_SESSION_ID",
                "cwd": "/absolute/project/path",
                "skill_name": "code-knowledge-builder",
                "ckb_skill_applied": True,
            },
        )
    manifest = {
        "schema_version": 1,
        "status": "rendered",
        "integration_version": INTEGRATION_VERSION,
        "harness": harness,
        "python": str(python),
        "ckb": str(ckb),
        "registry": str(registry),
        "project_opt_in_required": True,
        "session_skill_activation_required": True,
        "required_skill": "code-knowledge-builder",
        "transcript_parsing": False,
        "files": [str(path.relative_to(destination).as_posix()) for path in files],
    }
    manifest_path = write("integration.json", manifest)
    return {**manifest, "destination": str(destination), "manifest": str(manifest_path)}

#!/usr/bin/env python3
"""Create reproducible lite/full Skill archives after validating locked inputs."""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
import zipfile
from pathlib import Path, PurePosixPath


VERSION = "5.1.2"
ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", ".mypy_cache"}


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for path in ROOT.rglob("*"):
        if not path.is_file() or any(part in EXCLUDED_PARTS for part in path.parts):
            continue
        relative = path.relative_to(ROOT)
        if not include_runtime and relative.parts[:3] == ("assets", "runtime", "win-x64"):
            continue
        if path.suffix in {".pyc", ".pyo"}:
            continue
        result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())


def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path


def build(kind: str, dist: Path) -> dict:
    lock = json.loads((ROOT / "toolchain.lock.json").read_text(encoding="utf-8"))
    include_runtime = kind == "full-win-x64"
    if include_runtime:
        validate_full_payload(lock)
    files = source_files(include_runtime)
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder",
        "version": VERSION,
        "distribution": kind,
        "toolchain_lock_id": lock["lock_id"],
        "files": [
            {
                "path": path.relative_to(ROOT).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-{kind}-{VERSION}.zip"
    if archive_path.exists():
        archive_path.unlink()
    prefix = PurePosixPath("code-knowledge-builder")
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            relative = PurePosixPath(path.relative_to(ROOT).as_posix())
            info = zipfile.ZipInfo(str(prefix / relative), date_time=(2026, 8, 26, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
        manifest_info = zipfile.ZipInfo(str(prefix / "distribution" / "release-manifest.json"), date_time=(2026, 8, 26, 0, 0, 0))
        manifest_info.compress_type = zipfile.ZIP_DEFLATED
        manifest_info.external_attr = 0o100644 << 16
        archive.writestr(manifest_info, json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8") + b"\n")
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"ZIP CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(str(prefix / "distribution" / "release-manifest.json")))
        if archived_manifest != manifest:
            raise RuntimeError("archived release manifest differs from the generated manifest")
    result = {
        "status": "passed",
        "distribution": kind,
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-{kind}-{VERSION}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kind", choices=("lite", "full-win-x64", "both"), required=True)
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    kinds = ("lite", "full-win-x64") if args.kind == "both" else (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for path in ROOT.rglob("*"):
        if not path.is_file() or any(part in EXCLUDED_PARTS for part in path.parts):
            continue
        relative = path.relative_to(ROOT)
        if not include_runtime and relative.parts[:3] == ("assets", "runtime", "win-x64"):
            continue
        if path.suffix in {".pyc", ".pyo"}:
            continue
        result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())

def default_registry_path() -> Path:
    configured = os.environ.get("CKB_AUTOMATION_REGISTRY")
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "automation-registry.json"

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    value = os.path.normcase(os.path.normpath(value))
    return value.replace("\\", "/").rstrip("/")

def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"schema_version": AUTOMATION_SCHEMA_VERSION, "projects": []}
    value = json_load(path)
    if value.get("schema_version") in {1, 2} and isinstance(value.get("projects"), list):
        # Earlier registries matched either the repository only or repository
        # plus workspace roots.  Read both through the current hard activation
        # contract; the next registry write upgrades the document atomically.
        value = {
            **value,
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "projects": [
                {
                    **item,
                    "workspace_roots": list(item.get("workspace_roots") or []),
                    "required_skill": REQUIRED_SKILL,
                    "require_skill_activation": True,
                }
                for item in value["projects"]
            ],
        }
    if value.get("schema_version") != AUTOMATION_SCHEMA_VERSION or not isinstance(value.get("projects"), list):
        raise CkbError(f"unsupported automation registry: {path}")
    for item in value["projects"]:
        item.setdefault("workspace_roots", [])
        item["required_skill"] = REQUIRED_SKILL
        item["require_skill_activation"] = True
    return value

def registry_status(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "registry": str(registry),
        "project_count": len(value["projects"]),
        "projects": value["projects"],
    }

def _registration_for_event(registry: Path, cwd: Path, harness: str) -> tuple[dict[str, Any], str, str] | None:
    candidates: list[tuple[int, int, dict[str, Any], str, str]] = []
    for item in _read_registry(registry)["projects"]:
        if not item.get("enabled", False) or harness not in item.get("harnesses", []):
            continue
        if _is_within(cwd, item["repo_root"]):
            root = str(item["repo_root"])
            candidates.append((2, len(_path_key(root)), item, "repository", root))
        for workspace_root in item.get("workspace_roots", []):
            if _is_within(cwd, workspace_root):
                candidates.append((1, len(_path_key(workspace_root)), item, "workspace", str(workspace_root)))
    if not candidates:
        return None
    best = max(candidates, key=lambda value: (value[0], value[1]))
    tied = [value for value in candidates if value[:2] == best[:2] and value[2]["registration_id"] != best[2]["registration_id"]]
    if tied:
        raise CkbError(f"automation event cwd matches multiple registrations at the same priority: {cwd}")
    return best[2], best[3], best[4]

def _walk_values(value: Any) -> Iterator[tuple[str | None, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield str(key), child
            yield from _walk_values(child)
    elif isinstance(value, list):
        for child in value:
            yield None, child
            yield from _walk_values(child)

def _first_scalar(value: Any, keys: set[str]) -> str | None:
    lowered = {key.casefold() for key in keys}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).casefold() in lowered and isinstance(child, (str, int)):
                text = str(child).strip()
                if text:
                    return text
        for child in value.values():
            found = _first_scalar(child, keys)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _first_scalar(child, keys)
            if found:
                return found
    return None

def _text_content(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_text_content(item) for item in value]
        return "\n".join(item for item in parts if item)
    if isinstance(value, dict):
        direct = value.get("text")
        if isinstance(direct, str):
            return direct
        for key in ("content", "parts", "message", "delta", "info", "properties", "data"):
            if key in value:
                text = _text_content(value[key])
                if text:
                    return text
    return ""

def _event_name(raw: dict[str, Any]) -> str:
    for key in ("hook_event_name", "canonical_type", "event_type", "type"):
        value = raw.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    event = raw.get("event")
    if isinstance(event, dict) and isinstance(event.get("type"), str):
        return event["type"]
    return "unknown"

def _normalized_skill_name(value: Any) -> str:
    text = str(value or "").strip().casefold()
    return text.removeprefix("[").removesuffix("]").lstrip("$/").strip()

def _skill_name(raw: dict[str, Any], tool_name: str | None = None, tool_input: Any = None) -> str | None:
    for key, value in _walk_values(raw):
        if not key or key.casefold() not in _SKILL_METADATA_KEYS:
            continue
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, dict):
                item = item.get("name") or item.get("skill") or item.get("skill_name")
            if _normalized_skill_name(item) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    if str(tool_name or "").casefold() == "skill" and isinstance(tool_input, dict):
        for key in ("skill", "name", "skill_name", "command"):
            if _normalized_skill_name(tool_input.get(key)) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "")
    if _SKILL_PROMPT.search(prompt):
        return REQUIRED_SKILL
    return None

def _extract_paths(value: Any) -> list[str]:
    result: list[str] = []
    for key, child in _walk_values(value):
        if key and key.casefold() in _PATH_KEYS:
            if isinstance(child, str):
                result.append(child)
            elif isinstance(child, list):
                result.extend(str(item) for item in child if isinstance(item, (str, Path)))
        if isinstance(child, str):
            result.extend(match.strip() for match in _PATCH_PATH.findall(child))
    return list(dict.fromkeys(path.strip() for path in result if path.strip()))

def _redact_text(text: str, custom: list[re.Pattern[str]], max_chars: int) -> tuple[str, list[str]]:
    types: list[str] = []
    result = text
    for name, pattern in _DEFAULT_STRING_REDACTIONS:
        if pattern.search(result):
            types.append(name)
            if name == "credential-assignment":
                result = pattern.sub(lambda match: f"{match.group(1)}{match.group(2)}[REDACTED:CREDENTIAL]", result)
            else:
                result = pattern.sub(f"[REDACTED:{name.upper()}]", result)
    for index, pattern in enumerate(custom, 1):
        if pattern.search(result):
            types.append(f"custom-{index}")
            result = pattern.sub(f"[REDACTED:CUSTOM-{index}]", result)
    encoded = result.encode("utf-8")
    if len(encoded) > max_chars:
        data = encoded[:max_chars]
        while True:
            try:
                result = data.decode("utf-8") + f"\n[TRUNCATED:{len(encoded) - len(data)}-BYTES]"
                break
            except UnicodeDecodeError as exc:
                data = data[: exc.start]
        types.append("size-limit")
    return result, types

def redact_event(event: dict[str, Any], custom_patterns: list[str], max_chars: int) -> dict[str, Any]:
    custom = [re.compile(pattern) for pattern in custom_patterns]
    redaction_types: list[str] = []

    def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

    result = redact(event)
    result["redaction_count"] = len(redaction_types)
    result["redaction_types"] = sorted(set(redaction_types))
    return result

def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

def _automation_root(output: Path) -> Path:
    root = output / "workspace-meta" / "automation"
    for relative in ("spool/pending", "spool/processed", "spool/failed", "pending-reviews"):
        (root / relative).mkdir(parents=True, exist_ok=True)
    return root

def _git_status_paths(repo: Path) -> list[str]:
    prefix_result = run(["git", "rev-parse", "--show-prefix"], cwd=repo)
    prefix = prefix_result.stdout.strip().replace("\\", "/") if prefix_result.returncode == 0 else ""
    completed = run(["git", "status", "--porcelain=v1", "-z", "--untracked-files=all", "--", "."], cwd=repo)
    if completed.returncode:
        return []
    values: list[str] = []
    for record in completed.stdout.split("\0"):
        if len(record) < 4:
            continue
        path = record[3:].strip()
        if " -> " in path:
            path = path.rsplit(" -> ", 1)[1]
        if path:
            path = path.replace("\\", "/")
            if prefix and path.startswith(prefix):
                path = path[len(prefix) :]
            path = path.removeprefix("./")
            if path and _change_path_allowed(path):
                values.append(path)
    return sorted(set(values))

def _change_path_allowed(relative: str) -> bool:
    path = Path(relative.replace("\\", "/"))
    return not any(part.casefold() in _IGNORED_CHANGE_PARTS for part in path.parts) and path.suffix.casefold() not in _IGNORED_CHANGE_SUFFIXES

def _working_file_state(repo: Path, paths: list[str]) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for relative in paths:
        path = repo / relative
        if not path.is_file():
            result[relative] = {"exists": False, "size": 0, "content_sha256": None}
            continue
        digest = hashlib.sha256()
        try:
            with path.open("rb") as handle:
                for block in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(block)
            result[relative] = {"exists": True, "size": path.stat().st_size, "content_sha256": digest.hexdigest()}
        except OSError:
            result[relative] = {"exists": path.exists(), "size": -1, "content_sha256": None}
    return result

def _relative_changed_paths(paths: list[str], repo: Path, output: Path, event_cwd: Path | None = None) -> list[str]:
    result: list[str] = []
    for value in paths:
        candidate = Path(value)
        candidates = [candidate] if candidate.is_absolute() else [*([] if event_cwd is None else [event_cwd / candidate]), repo / candidate]
        for possible in candidates:
            if (
                not candidate.is_absolute()
                and event_cwd is not None
                and not _is_within(event_cwd, repo)
                and possible == repo / candidate
                and not possible.exists()
                and run(["git", "ls-files", "--error-unmatch", "--", candidate.as_posix()], cwd=repo).returncode != 0
            ):
                # A workspace-level relative path that is neither present nor
                # tracked in the source repository belongs to scratch/output,
                # not to an imaginary path with the same spelling under repo.
                continue
            try:
                resolved = possible.resolve()
            except OSError:
                continue
            if not _is_within(resolved, repo) or _is_within(resolved, output):
                continue
            try:
                relative = resolved.relative_to(repo.resolve()).as_posix()
            except ValueError:
                continue
            if relative and relative != "." and _change_path_allowed(relative):
                result.append(relative)
                break
    return sorted(set(result))

def _drain_lock(output: Path, timeout: float = 3.0) -> Iterator[bool]:
    root = _automation_root(output)
    lock = root / "drain.lock"
    deadline = time.monotonic() + timeout
    acquired = False
    while time.monotonic() < deadline:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
            os.close(descriptor)
            acquired = True
            break
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink()
                    continue
            except FileNotFoundError:
                continue
            time.sleep(0.05)
    try:
        yield acquired
    finally:
        if acquired:
            try:
                lock.unlink()
            except FileNotFoundError:
                pass

def default_session_id(harness: str) -> str | None:
    for key in ("CKB_SESSION_ID", *_SESSION_ENVIRONMENT.get(harness, ())):
        value = os.environ.get(key)
        if value and value.strip():
            return value.strip()
    return None

def _skill_activation(output: Path, repo: Path, harness: str, session_id: str) -> dict[str, Any] | None:
    path = output / AUTOMATION_DATABASE
    if not path.is_file():
        path = initialize_automation_database(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute(
            "SELECT activation_key,activation_source,activated_at_utc FROM skill_activations WHERE harness=? AND external_session_id=? AND repo_root=? AND skill_name=?",
            (harness, session_id, str(repo), REQUIRED_SKILL),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return None
    return {"activation_key": row[0], "activation_source": row[1], "activated_at_utc": row[2]}

def _explicit_skill_application(event: dict[str, Any]) -> str | None:
    if event.get("skill_name") == REQUIRED_SKILL:
        if event["canonical_type"] == "skill.applied":
            return "native-skill-event"
        raw = event.get("raw") or {}
        if raw.get("ckb_skill_applied") is True:
            return "explicit-payload-field"
        if _SKILL_PROMPT.search(str(event.get("prompt") or "")):
            return "explicit-prompt-invocation"
        return "harness-skill-metadata"
    return None

def _resolve_turn(
    connection: sqlite3.Connection,
    event: dict[str, Any],
    session_key: str,
) -> tuple[str | None, str | None]:
    canonical = event["canonical_type"]
    if canonical in {"skill.applied", "session.start", "session.end"}:
        return None, None
    supplied = event.get("turn_id")
    if supplied:
        external = str(supplied)
        row = connection.execute("SELECT turn_key FROM turns WHERE session_key=? AND external_turn_id=?", (session_key, external)).fetchone()
        if row:
            return str(row[0]), external
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    active = connection.execute(
        "SELECT turn_key,external_turn_id,prompt FROM turns WHERE session_key=? AND status='active' ORDER BY ordinal DESC LIMIT 1",
        (session_key,),
    ).fetchone()
    if canonical == "turn.prompt":
        prompt = event.get("prompt") or ""
        if active and str(active[2]) == prompt:
            return str(active[0]), str(active[1])
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        external = f"turn-{ordinal:06d}"
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    if active:
        return str(active[0]), str(active[1])
    if canonical in {"turn.assistant", "turn.stop", "compact.before", "compact.after"}:
        latest = connection.execute(
            "SELECT turn_key,external_turn_id FROM turns WHERE session_key=? ORDER BY ordinal DESC LIMIT 1",
            (session_key,),
        ).fetchone()
        if latest:
            return str(latest[0]), str(latest[1])
    ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
    external = f"turn-{ordinal:06d}"
    key = stable_id("autoturn", session_key, external)
    connection.execute(
        "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
        (key, session_key, external, ordinal, "active", event["received_at_utc"]),
    )
    return key, external

def _event_id(event: dict[str, Any], session_key: str, turn_key: str | None) -> str:
    explicit = event.get("external_event_id")
    if explicit:
        return stable_id("autoevent", event["harness"], explicit)
    identity_payload = {
        "canonical_type": event["canonical_type"],
        "prompt": event.get("prompt") or "",
        "assistant_message": event.get("assistant_message") or "",
        "tool_name": event.get("tool_name"),
        "tool_use_id": event.get("tool_use_id"),
        "changed_paths": event.get("changed_paths") or [],
        "source": event.get("source"),
    }
    return stable_id(
        "autoevent",
        event["harness"],
        session_key,
        turn_key or "session",
        event["canonical_type"],
        event.get("tool_use_id") or "",
        json.dumps(identity_payload, ensure_ascii=False, sort_keys=True),
    )

